// =============================================================================
// inbound-debounce-config.js — the single reading of the inbound debounce env.
// -----------------------------------------------------------------------------
// INBOUND_DEBOUNCE_SECONDS: how long a contact must stay quiet before their
// pending messages become one turn (sliding window, default 6, 0 disables,
// capped at 60). INBOUND_DEBOUNCE_MAX_WAIT_SECONDS: how long a customer who
// keeps typing can defer that turn (default 30, never below the window, capped
// at 300). An unreadable value keeps the default rather than disabling.
// Code nodes get this file prepended through `runtimes` in
// tests/scripts/sync-workflow-nodes.mjs; Node harnesses require it.
// =============================================================================

const DEFAULT_INBOUND_DEBOUNCE_SECONDS = 6;
const MAX_INBOUND_DEBOUNCE_SECONDS = 60;
const DEFAULT_INBOUND_DEBOUNCE_MAX_WAIT_SECONDS = 30;
const MAX_INBOUND_DEBOUNCE_MAX_WAIT_SECONDS = 300;

const readWholeSeconds = (value, fallback, max) => {
  const raw = String(value ?? '').trim();
  if (!/^\d+$/.test(raw)) return fallback;
  return Math.min(max, Number(raw));
};

const resolveInboundDebounce = (env) => {
  const source = env || {};
  const seconds = readWholeSeconds(
    source.INBOUND_DEBOUNCE_SECONDS,
    DEFAULT_INBOUND_DEBOUNCE_SECONDS,
    MAX_INBOUND_DEBOUNCE_SECONDS,
  );
  if (seconds === 0) return { seconds: 0, max_wait_seconds: 0 };
  const maxWait = readWholeSeconds(
    source.INBOUND_DEBOUNCE_MAX_WAIT_SECONDS,
    DEFAULT_INBOUND_DEBOUNCE_MAX_WAIT_SECONDS,
    MAX_INBOUND_DEBOUNCE_MAX_WAIT_SECONDS,
  );
  return { seconds, max_wait_seconds: Math.max(seconds, maxWait) };
};

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { resolveInboundDebounce };
}


// The recovery claim runs from three places: the minute schedule and the
// dispatcher's "next inbox event" claim every settled queue; the entry
// webhook's debounce waiter scopes the claim to its own contact queue, so one
// contact's drain never processes another contact's turn in its execution.
const input = items[0]?.json ?? {};
const debounce = resolveInboundDebounce($env);
const scope = String(input.queue_scope_inbound_event_id ?? '').trim();

return [{ json: {
  stale_seconds: Math.max(60, Number($env.INBOUND_PROCESSING_STALE_SECONDS || 600)),
  batch_size: Math.max(1, Math.min(100, Number($env.INBOUND_RECOVERY_BATCH_SIZE || 20))),
  max_attempts: Math.max(1, Number($env.INBOUND_MAX_PROCESSING_ATTEMPTS || 5)),
  debounce_seconds: debounce.seconds,
  debounce_max_wait_seconds: debounce.max_wait_seconds,
  queue_scope_inbound_event_id: /^\d+$/.test(scope) ? scope : null,
} }];

return items.map((item) => {
  const durable = item.json.downstream_payload && typeof item.json.downstream_payload === 'object'
    ? item.json.downstream_payload : {};
  const hasDurableResult = Object.keys(durable).length > 0;
  const base = hasDurableResult ? durable : (item.json.normalized_payload || {});
  const normalizedBase = Object.fromEntries(Object.entries(base).map(([key, value]) => {
    const normalized = typeof value === 'string' && ['null', 'undefined'].includes(value.trim().toLowerCase()) ? null : value;
    return [key, normalized];
  }));
  return { json: {
    ...normalizedBase,
    source_number_id: item.json.source_number_id,
    inbound_event_id: item.json.inbound_event_id,
    processing_token: item.json.processing_token,
    should_process: true,
    recovered_event: true,
    resume_downstream: hasDurableResult,
  } };
});
